import argparse
events=[]
class Flag:
 def __bool__(self):
  with open('/repo/input.txt') as f:events.append(f.read())
  return False
p=argparse.ArgumentParser(add_help=False,exit_on_error=False)
p.add_argument('--x',required=Flag())
try:p.parse_args([])
except argparse.ArgumentError:print('required')
print(events)

